const gpId=p=>`${p}-${Date.now().toString(36)}-${Math.random().toString(36).slice(2,6)}`;
const gpHead=(k,t,d,a='')=>`<div class="page-head"><div><div class="eyebrow">${k}</div><h1 class="page-title">${t}</h1><p class="page-description">${d}</p></div><div class="head-actions">${a}</div></div>`;
const gpBtn=(a,t,id='',cls='',extra='')=>`<button class="btn ${cls}" data-action="${a}" data-id="${esc(id)}" ${extra}>${t}</button>`;
const gpDate=d=>new Date(d).toLocaleDateString('fr-FR',{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'});
const gpTabs=(items,active,action)=>`<div class="filter-bar">${items.map(([v,t])=>`<button class="filter-btn ${v===active?'active':''}" data-action="${action}" data-value="${v}" aria-pressed="${v===active}">${t}</button>`).join('')}</div>`;
const gpOptions=(items,value)=>items.map(([v,t])=>`<option value="${esc(v)}" ${v===value?'selected':''}>${esc(t)}</option>`).join('');
const gpStatus=a=>badge(a.status==='active'?'Actif':a.status==='pilot'?'Pilote':'Suspendu',a.status==='active'?'green':a.status==='pilot'?'purple':'amber');
const permissionGroups=[{title:'Applications',items:[['apps.agents','Ouvrir Agents'],['apps.teams','Ouvrir Teams']]},{title:'Gouvernance',items:[['goals.view','Voir les objectifs'],['goals.manage','Définir les objectifs'],['gaps.manage','Arbitrer les blocages'],['workforce.view','Voir l’organisation'],['workforce.manage','Gérer l’organisation'],['transformation.view','Voir la transformation'],['transformation.manage','Piloter la transformation'],['policies.view','Voir les règles'],['policies.manage','Gérer les règles'],['security.events','Voir les événements sécurité'],['spend.view','Voir les coûts'],['roles.manage','Gérer les rôles'],['connectors.approve','Approuver les connecteurs'],['models.manage','Gérer les modèles']]},{title:'Équipes',items:[['teams.goals','Définir les objectifs d’équipe'],['teams.agents','Ajouter des agents'],['skills.share','Partager des compétences'],['connectors.build','Créer des connecteurs']]},{title:'Actions',items:[['data.read','Lire les données'],['data.write','Modifier les données'],['external.send','Communiquer à l’extérieur'],['data.customer','Utiliser les données clients'],['money.move','Engager des dépenses'],['production.change','Modifier la production'],['legal.commit','Prendre un engagement juridique'],['access.grant','Accorder un accès']]}];
const allPermissions=permissionGroups.flatMap(g=>g.items.map(i=>i[0]));
const roleDefinition=(id,name,type,scope,permissions,cap=0)=>({id,name,type,scope,permissions,moneyCap:cap,description:`Plafond des permissions du rôle ${name}. Les mandats peuvent réduire ce périmètre.`});
function adminSeed(s){return {roles:[roleDefinition('r-executive','Direction générale','human','organization',['apps.teams','goals.view','goals.manage','gaps.manage','workforce.view','transformation.view','transformation.manage','spend.view']),roleDefinition('r-transformation','Transformation','human','organization',['apps.agents','apps.teams','goals.view','goals.manage','gaps.manage','workforce.view','workforce.manage','transformation.view','transformation.manage','spend.view','teams.goals','teams.agents','skills.share']),roleDefinition('r-security','Sécurité','human','organization',['apps.teams','goals.view','workforce.view','policies.view','policies.manage','security.events','connectors.approve']),roleDefinition('r-finance','Finance','human','organization',['apps.teams','goals.view','spend.view','money.move'],10000),roleDefinition('r-people','Ressources humaines','human','organization',['apps.teams','workforce.view','workforce.manage','transformation.view']),roleDefinition('r-group','Responsable de fonction','human','group',['apps.agents','apps.teams','goals.view','goals.manage','gaps.manage','workforce.view','workforce.manage','teams.goals','teams.agents','spend.view']),roleDefinition('r-team','Responsable d’équipe','human','team',['apps.agents','apps.teams','goals.view','workforce.view','teams.goals','teams.agents','data.read','data.write']),roleDefinition('r-member','Collaborateur','human','own',['apps.agents','apps.teams','goals.view','data.read']),roleDefinition('r-admin','Administrateur','human','organization',allPermissions,10000),roleDefinition('r-reader','Lecteur','agent','own',['data.read']),roleDefinition('r-worker','Opérateur métier','agent','team',['data.read','data.write']),roleDefinition('r-facing','Relation client','agent','team',['data.read','data.write','external.send','data.customer']),roleDefinition('r-operator','Opérateur technique','agent','group',['data.read','data.write','production.change'])],assignments:Object.fromEntries(s.agents.map(a=>[a.id,a.type==='agent'?'r-worker':a.id==='h-matthieu'?'r-transformation':a.id==='h-sophie'?'r-security':a.id==='h-lea'?'r-member':'r-group'])),models:[{id:'model-eu',name:'Modèle généraliste UE',provider:'Passerelle modèles',region:'Europe',enabled:true,monthlyCap:4500,purpose:'Rédaction et synthèse'},{id:'model-reason',name:'Modèle de raisonnement',provider:'Passerelle modèles',region:'Europe',enabled:true,monthlyCap:2500,purpose:'Analyse complexe et contrôle'},{id:'model-local',name:'Modèle local',provider:'Infrastructure interne',region:'Sur site',enabled:false,monthlyCap:1000,purpose:'Données à accès restreint'}],connectorReviews:[{id:'review-crm',connectorId:'crm',name:'CRM · lecture des opportunités',requester:'Quill',owner:'Sophie Laurent',scope:'Lecture des opportunités et pièces approuvées',risk:'Données clients',status:'pending',requestedAt:'2026-11-04T08:00:00Z',evidence:'Accès en lecture seule ; périmètre Distribution ; aucun secret renseigné.'},{id:'review-cost',connectorId:'accounting',name:'Comptabilité · centres de coûts',requester:'Nova',owner:'Claire Martin',scope:'Lecture des coûts agrégés par équipe',risk:'Données financières',status:'pending',requestedAt:'2026-11-03T10:00:00Z',evidence:'Source fictive ; granularité agrégée ; usage limité au pilotage.'}]};}
function securitySeed(){return {events:[{id:'sec-001',title:'Un script non enregistré a utilisé une identité humaine',actor:'Automatisation historique',policyId:'pol-identity',kind:'broken',status:'open',time:'2026-11-04T07:35:00Z',why:'Un ancien traitement du scénario est exécuté hors du registre des agents.',evidence:['Identité observée : compte partagé de démonstration','Aucun mandat associé au traitement','Aucune connexion réelle utilisée'],resolution:''},{id:'sec-002',title:'Une communication externe attend sa validation',actor:'Quill',policyId:'pol-external',kind:'escalation',status:'waiting',time:'2026-11-04T08:20:00Z',why:'La proposition engage des conditions nouvelles ; la règle impose une validation préalable.',evidence:['Dossier Horizon','Julien Moreau désigné comme valideur','Envoi suspendu dans la simulation'],decisionId:'d-rfp',resolution:''},{id:'sec-003',title:'Une source non autorisée a été bloquée',actor:'Beacon',policyId:'pol-data',kind:'broken',status:'contained',time:'2026-11-03T15:10:00Z',why:'La source proposée ne figure pas au catalogue approuvé ; le contrôle a arrêté la demande.',evidence:['Aucune lecture de la source effectuée','Demande inscrite dans le journal','Événement fictif de test des contrôles'],resolution:'Blocage automatique ; examen de la source requis.'}],accessReviews:[{id:'access-01',actorId:'a-quill',permission:'external.send',scope:'Distribution',owner:'Julien Moreau',status:'pending',dueAt:'2026-11-15',evidence:'Revoir la nécessité d’un droit d’envoi externe ; validation humaine toujours requise.'},{id:'access-02',actorId:'h-claire',permission:'money.move',scope:'Opérations · plafond 5 000 €',owner:'Matthieu Keip',status:'pending',dueAt:'2026-11-15',evidence:'Vérifier le responsable de budget et la séparation des responsabilités.'}]};}
export function initGovernancePlus(){const s=getState();if(s.governancePlus?.version===2)return;update(st=>{const current=st.governancePlus||{};st.governancePlus={...current,version:2,admin:current.admin||adminSeed(st),security:current.security||securitySeed(),...(!current.transformation?{transformation:createInsightsSeed(st).transformation}:{}),...(!current.spend?{spend:createInsightsSeed(st).spend}:{})};st.agents.forEach(a=>{if(a.managerId===undefined)a.managerId=st.agents.find(x=>x.type==='human'&&x.name===a.manager)?.id||null;});st.goals.forEach((g,i)=>{if(g.parentId===undefined)g.parentId=g.id==='g-autonomy'?null:'g-autonomy';g.krs.forEach((k,j)=>{if(!k.id)k.id=`${g.id}-kr-${j}`;if(k.baseline===undefined){const p=Math.min(.95,Number(g.progress)/100);k.baseline=Math.max(0,Math.round((k.current-p*k.target)/(1-p)*10)/10);}if(!k.source)k.source='Mesure du scénario · processus associés';if(!k.series)k.series=[k.baseline,...[.25,.52,.78].map(r=>Math.round((k.baseline+(k.current-k.baseline)*r)*10)/10),k.current];});});st.gaps.forEach(g=>{g.workerId=g.workerId||st.processes.find(p=>p.id===g.processId)?.agentIds?.[0];g.options.forEach((o,j)=>{o.leadTime=o.leadTime||(['training'].includes(o.action)?'2 semaines':o.action==='data-request'?'1 semaine':'Cette semaine');o.cost=o.cost??0;});});},'Espace de gouvernance enrichi','Initialisation des fonctions de pilotage illustratives.');}

let workforceMode='hierarchy', workforceType='all', workforceTeam='all', workforceManager='all', securityTab='events', eventFilter='all', adminTab='roles', roleType='all';
function gp(s){return s.governancePlus;}
export function validateReportingLine(s,actorId,managerId){const actor=s.agents.find(a=>a.id===actorId);if(!actor)return 'Collaborateur introuvable.';if(!managerId)return '';const manager=s.agents.find(a=>a.id===managerId);if(!manager||manager.type!=='human')return 'Le responsable doit être une personne du registre.';if(manager.id===actorId)return 'Une personne ne peut pas être son propre responsable.';const seen=new Set([actorId]);let cursor=manager;while(cursor){if(seen.has(cursor.id))return 'Ce rattachement créerait un cycle hiérarchique.';seen.add(cursor.id);const nextId=cursor.managerId||s.agents.find(a=>a.type==='human'&&a.name===cursor.manager)?.id;cursor=s.agents.find(a=>a.id===nextId);}return '';}
function childrenOf(s,a){return s.agents.filter(x=>x.id!==a.id&&(x.managerId===a.id||(!x.managerId&&x.manager===a.name)));}
function descendants(s,id,seen=new Set()){if(seen.has(id))return [];seen.add(id);const a=s.agents.find(a=>a.id===id);return a?childrenOf(s,a).flatMap(c=>[c,...descendants(s,c.id,seen)]):[];}
function lineage(s,a){const seen=new Set([a.id]), names=[];let p=s.agents.find(x=>x.id===a.managerId)||s.agents.find(x=>x.name===a.manager);while(p&&!seen.has(p.id)){seen.add(p.id);names.unshift(p.name);p=s.agents.find(x=>x.id===p.managerId)||s.agents.find(x=>x.name===p.manager);}return names;}
function workforceMatches(s,a){return (workforceType==='all'||a.type===workforceType)&&(workforceTeam==='all'||a.team===workforceTeam)&&(workforceManager==='all'||a.id===workforceManager||descendants(s,workforceManager).some(x=>x.id===a.id));}
function actorTile(a,s){const reports=childrenOf(s,a);return `<button class="gp-actor-tile" data-action="gp-person" data-id="${esc(a.id)}">${avatar(a)}<span><strong>${esc(a.name)}</strong><small>${esc(a.role)}</small><span class="gp-actor-team">${esc(a.team)}${reports.length?` · ${reports.length} rattachement${reports.length>1?'s':''}`:''}</span></span>${a.type==='agent'?badge('Agent','purple'):badge('Humain','neutral')}</button>`;}
function treeNode(a,s,path=new Set()){if(path.has(a.id))return '';const next=new Set(path);next.add(a.id);const children=childrenOf(s,a),filtered=children.filter(x=>workforceMatches(s,x)||descendants(s,x.id).some(y=>workforceMatches(s,y)));return `<li class="gp-tree-node">${actorTile(a,s)}${filtered.length?`<ul>${filtered.map(c=>treeNode(c,s,next)).join('')}</ul>`:''}</li>`;}
export function renderWorkforce(s){const list=s.agents.filter(a=>workforceMatches(s,a));const roots=s.agents.filter(a=>!s.agents.some(x=>x.id!==a.id&&(x.id===a.managerId||x.name===a.manager))).filter(a=>workforceMatches(s,a)||descendants(s,a.id).some(x=>workforceMatches(s,x)));return `${gpHead('REGISTRE DE L’ORGANISATION','Une équipe, plusieurs formes de talent.','Qui porte quelle responsabilité ? Explorez les équipes, les mandats et les lignes de management.',gpBtn('gp-create-person',`${icon('plus',16)} Ajouter une personne`,'','btn-primary'))}<div class="gp-workforce-summary"><div><strong>${s.agents.filter(a=>a.type==='human').length}</strong><span>personnes</span></div><div><strong>${s.agents.filter(a=>a.type==='agent').length}</strong><span>agents</span></div><div><strong>${new Set(s.agents.map(a=>a.team)).size}</strong><span>fonctions</span></div><div><strong>${s.agents.filter(a=>a.type==='agent'&&a.status==='pilot').length}</strong><span>agents en pilote</span></div></div><div class="row between gp-toolbar">${gpTabs([['hierarchy','Hiérarchie'],['registry','Registre']],workforceMode,'gp-workforce-mode')}<div class="row">${gpTabs([['all','Tous'],['human','Personnes'],['agent','Agents']],workforceType,'gp-workforce-type')}${gpBtn('gp-workforce-filters',`${icon('filter',15)} Filtrer`,'','btn-sm')}</div></div>${workforceTeam!=='all'||workforceManager!=='all'?`<div class="notice">Filtres : ${esc(workforceTeam==='all'?'toutes les fonctions':workforceTeam)} · ${esc(s.agents.find(a=>a.id===workforceManager)?.name||'tous les responsables')} ${gpBtn('gp-workforce-clear','Effacer','','btn-ghost btn-sm')}</div>`:''}${workforceMode==='hierarchy'?`<div class="card gp-tree-container"><ul class="gp-tree">${roots.map(a=>treeNode(a,s)).join('')||empty('Aucun rattachement','Modifiez les filtres pour afficher votre organisation.')}</ul></div>`:`<div class="card table-wrap"><table class="data-table"><thead><tr><th>Personne ou agent</th><th>Fonction</th><th>Responsable</th><th>Activité suivie</th><th>Qualité</th><th>Situation</th><th></th></tr></thead><tbody>${list.map(a=>`<tr><td><div class="person">${avatar(a)}<span><strong>${esc(a.name)}</strong><small class="muted">${esc(a.role)}</small></span></div></td><td>${esc(a.team)}</td><td>${esc(a.manager)}</td><td>${fmt(a.hours)} h</td><td>${a.type==='agent'?`${a.quality} %`:'Non mesurée'}</td><td>${gpStatus(a)}</td><td>${gpBtn('gp-person','Voir',a.id,'btn-sm btn-ghost')}</td></tr>`).join('')}</tbody></table>${!list.length?empty('Aucun membre','Essayez un autre filtre.'):''}</div>`}<p class="form-help">Le registre présente le travail, les objectifs et les heures suivies. Les conversations privées ne sont pas exposées.</p>`;}
function personDrawer(a,s,ctx){const reports=childrenOf(s,a), goals=s.goals.filter(g=>g.owner===a.name||g.id===a.objectiveId),processes=s.processes.filter(p=>p.owner===a.name||p.agentIds.includes(a.id));const path=lineage(s,a);ctx.drawer({title:a.name,subtitle:`${a.role} · ${a.team}`,body:`<div class="row">${avatar(a,'lg')}${gpStatus(a)}${badge(a.type==='agent'?'Agent':'Personne','purple')}</div><p class="gp-lineage">${[...path,a.name].map(esc).join(' / ')}</p><div class="detail-grid"><div class="detail-item"><span>Responsable</span><strong>${esc(a.manager)}</strong></div><div class="detail-item"><span>Travail suivi ce mois</span><strong>${fmt(a.hours)} h</strong></div><div class="detail-item"><span>Qualité des résultats</span><strong>${a.type==='agent'?`${a.quality} % acceptés`:'Non mesurée'}</strong></div><div class="detail-item"><span>Rôle d’accès</span><strong>${esc(gp(s).admin.roles.find(r=>r.id===gp(s).admin.assignments[a.id])?.name||'À attribuer')}</strong></div></div><h3>Objectifs portés</h3>${goals.map(g=>gpBtn('gov-goal-detail',`${icon('target',16)} ${esc(g.title)}`,g.id,'gp-full-row')).join('')||'<p class="muted small">Aucun objectif associé.</p>'}<h3>Processus</h3>${processes.map(p=>gpBtn('wf-open',`${icon('workflow',16)} ${esc(p.name)}`,p.id,'gp-full-row')).join('')||'<p class="muted small">Aucun processus attribué.</p>'}${reports.length?`<h3>Rattachements directs</h3>${reports.map(r=>actorTile(r,s)).join('')}`:''}<div class="drawer-actionbar">${gpBtn('gp-edit-person','Modifier le rattachement',a.id,'btn-primary')}${a.type==='agent'?gpBtn('org-edit-mandate','Modifier le mandat',a.id):''}</div><p class="form-help">Les heures et résultats de cet espace sont fictifs ; aucune donnée RH réelle.</p>`});}
function personForm(a,s,ctx){const isNew=!a,initial=a||{name:'',role:'',team:'Opérations',managerId:'h-matthieu',status:'active'};ctx.closeDrawer();ctx.modal({title:isNew?'Ajouter une personne':'Modifier le rattachement',subtitle:isNew?'Définissez sa place dans l’organisation.':initial.name,submitLabel:isNew?'Créer la personne':'Enregistrer',body:`${isNew?'<div class="field"><label for="gp-person-name">Nom</label><input id="gp-person-name" name="name" required maxlength="80"></div>':''}<div class="field"><label for="gp-person-role">Fonction</label><input id="gp-person-role" name="role" value="${esc(initial.role)}" required maxlength="100"></div><div class="form-grid"><div class="field"><label for="gp-person-team">Équipe</label><input id="gp-person-team" name="team" value="${esc(initial.team)}" required maxlength="80" list="gp-team-options"><datalist id="gp-team-options">${[...new Set(s.agents.map(x=>x.team))].map(t=>`<option value="${esc(t)}">`).join('')}</datalist></div><div class="field"><label for="gp-person-manager">Responsable humain</label><select id="gp-person-manager" name="managerId">${gpOptions([['','Direction générale'],...s.agents.filter(x=>x.type==='human'&&x.id!==a?.id).map(x=>[x.id,x.name])],initial.managerId||'')}</select></div><div class="field"><label for="gp-person-status">Situation</label><select id="gp-person-status" name="status">${gpOptions([['active','Actif'],...(a?.type==='agent'?[['pilot','Pilote']]:[]),['paused','Suspendu']],initial.status)}</select></div></div>`,onSubmit:fd=>{const managerId=String(fd.get('managerId')),name=isNew?String(fd.get('name')||'').trim():a.name,role=String(fd.get('role')||'').trim(),team=String(fd.get('team')||'').trim();if(!name||!role||!team){ctx.toast('Renseignez le nom, la fonction et l’équipe.');return false;}if(isNew&&s.agents.some(x=>x.name.toLowerCase()===name.toLowerCase())){ctx.toast('Ce nom existe déjà dans le registre.');return false;}const actorId=a?.id||gpId('human'),manager=s.agents.find(x=>x.id===managerId),current=ctx.getState();const virtual=isNew?{...current,agents:[...current.agents,{id:actorId,type:'human'}]}:current,error=validateReportingLine(virtual,actorId,managerId);if(error){ctx.toast(error);return false;}if(a?.type==='agent'&&!manager){ctx.toast('Un agent doit avoir un responsable humain.');return false;}ctx.update(st=>{if(isNew){st.agents.push({id:actorId,name,initials:name.split(' ').map(x=>x[0]).slice(0,2).join(''),role,type:'human',team,manager:manager?.name||'Direction générale',managerId:managerId||null,status:String(fd.get('status')),autonomy:1,quality:0,hours:0,cost:0,skills:[],objectiveId:'',mandate:{mission:role,tools:[],limits:'Dans le cadre du rôle attribué.',expires:'2027-12-31',reviewer:manager?.name||'Direction générale'}});st.governancePlus.admin.assignments[actorId]='r-member';}else{const x=st.agents.find(x=>x.id===a.id);Object.assign(x,{role,team,manager:manager?.name||'Direction générale',managerId:managerId||null,status:String(fd.get('status'))});if(x.mandate)x.mandate.reviewer=manager?.name||'Direction générale';}},isNew?'Personne ajoutée':'Rattachement modifié',name);ctx.toast('Le registre est mis à jour.');}});}

function isSecurityView(s){return String(s.workspace?.personaId||'').toLowerCase().includes('security')||s.workspace?.actorId==='h-sophie';}
function securityEvents(s){return gp(s).security.events;}
export function renderSecurity(s){const data=gp(s).security, events=securityEvents(s),filtered=events.filter(e=>eventFilter==='all'||e.kind===eventFilter);return `${gpHead('GOUVERNANCE · SÉCURITÉ','Les règles, et ce qui se passe vraiment.','Reliez chaque exception à son auteur, sa règle et aux preuves de sa résolution.')}<div class="stat-grid"><div class="stat-card"><span class="stat-label">Violations ouvertes</span><strong class="stat-value">${events.filter(e=>e.kind==='broken'&&e.status==='open').length}</strong><span class="stat-foot">Examen sécurité requis</span></div><div class="stat-card"><span class="stat-label">Escalades en attente</span><strong class="stat-value">${events.filter(e=>e.kind==='escalation'&&e.status==='waiting').length}</strong><span class="stat-foot">Décision d’un responsable</span></div><div class="stat-card"><span class="stat-label">Revues d’accès</span><strong class="stat-value">${data.accessReviews.filter(r=>r.status==='pending').length}</strong><span class="stat-foot">Droits à recertifier</span></div><div class="stat-card"><span class="stat-label">Connecteurs à examiner</span><strong class="stat-value">${gp(s).admin.connectorReviews.filter(r=>r.status==='pending').length}</strong><span class="stat-foot">Périmètres de démonstration</span></div></div>${gpTabs([['events','Événements'],['policies','Règles'],['access','Revues d’accès'],['connectors','Connecteurs']],securityTab,'gp-security-tab')}${securityTab==='policies'?`<div class="gp-embedded-policies">${renderPolicies(s)}</div>`:securityTab==='access'?renderAccess(s):securityTab==='connectors'?renderConnectorReviews(s):`${gpTabs([['all','Tous'],['broken','Règle enfreinte'],['escalation','Passé à un humain']],eventFilter,'gp-event-filter')}<div class="stack">${filtered.map(e=>`<article class="card gp-event-card"><div class="icon-box ${e.kind==='broken'?'amber':'purple'}">${icon(e.kind==='broken'?'alert':'user',20)}</div><div><div class="row"><span class="eyebrow">${esc(e.id)}</span>${badge(({open:'Ouvert',waiting:'En attente',contained:'Contenu',resolved:'Résolu'})[e.status]||e.status,e.status==='resolved'?'green':e.status==='contained'?'neutral':'amber')}</div><h2 class="card-title">${esc(e.title)}</h2><p class="muted small">${esc(e.actor)} · ${esc(s.policies.find(p=>p.id===e.policyId)?.title||e.policyId)} · ${gpDate(e.time)}</p></div>${gpBtn('gp-security-event','Examiner',e.id,'btn-sm')}</article>`).join('')}</div>`}<p class="form-help">Les événements fournis sont des scénarios fictifs de sécurité ; aucune infrastructure réelle n’est inspectée.</p>`;}
function renderAccess(s){return `<div class="stack">${gp(s).security.accessReviews.map(r=>{const a=s.agents.find(x=>x.id===r.actorId),permission=permissionGroups.flatMap(g=>g.items).find(x=>x[0]===r.permission)?.[1]||r.permission;return `<article class="card gp-review-card"><div class="row between"><div class="person">${a?avatar(a):icon('user')}<div><h3>${esc(a?.name||r.actorId)}</h3><p class="muted small">${esc(permission)} · ${esc(r.scope)}</p></div></div>${badge(r.status==='pending'?'À recertifier':r.status==='approved'?'Maintenu':'Retiré',r.status==='pending'?'amber':r.status==='approved'?'green':'neutral')}</div><p>${esc(r.evidence)}</p><div class="row between"><span class="muted small">${esc(r.owner)} · échéance ${esc(r.dueAt)}</span>${r.status==='pending'?gpBtn('gp-access-review','Examiner l’accès',r.id,'btn-sm'):''}</div></article>`;}).join('')}</div>`;}
function renderConnectorReviews(s){const connections=s.capabilities?.connections||[];return `${connections.length?`<h3 class="section-title">Connecteurs installés</h3><div class="stack">${connections.map(c=>`<article class="card gp-review-card"><div class="row between"><div><h3>${esc(c.name)}</h3><p class="muted small">${esc(c.owner)} · ${(c.scopes||[]).map(esc).join(', ')}</p></div>${badge(c.status==='connected'?'Connecté en démo':c.status==='needs-review'?'Revue requise':'Révoqué',c.status==='connected'?'green':c.status==='needs-review'?'amber':'neutral')}</div><p class="muted small">${esc(c.testResult?.detail||'Configuration à tester avant approbation. Aucun accès réel.')}</p><button class="btn btn-sm" data-action="cap-connection-detail" data-id="${esc(c.id)}">Tester et examiner les droits</button></article>`).join('')}</div><h3 class="section-title">Demandes de raccordement</h3>`:''}<div class="stack">${gp(s).admin.connectorReviews.map(r=>`<article class="card gp-review-card"><div class="row between"><div><div class="eyebrow">${esc(r.risk)}</div><h3>${esc(r.name)}</h3></div>${badge(r.status==='pending'?'Revue requise':r.status==='approved'?'Autorisé en démo':'Refusé',r.status==='pending'?'amber':r.status==='approved'?'green':'red')}</div><p>${esc(r.scope)}</p><p class="muted small">${esc(r.evidence)}</p><div class="row between"><span class="muted small">Demandé par ${esc(r.requester)} · ${esc(r.owner)}</span><div class="row">${gpBtn('nav','Voir les intégrations','','btn-sm btn-ghost','data-value="integrations"')}${r.status==='pending'?gpBtn('gp-connector-review','Examiner',r.id,'btn-sm'):''}</div></div></article>`).join('')}</div>`;}
function eventDrawer(e,s,ctx){ctx.drawer({title:e.title,subtitle:`${e.id} · ${gpDate(e.time)}`,body:`${badge(({open:'Ouvert',waiting:'En attente',contained:'Contenu',resolved:'Résolu'})[e.status]||e.status,e.status==='resolved'?'green':'amber')}<div class="detail-grid"><div class="detail-item"><span>Auteur</span><strong>${esc(e.actor)}</strong></div><div class="detail-item"><span>Règle</span><strong>${esc(s.policies.find(p=>p.id===e.policyId)?.title||e.policyId)}</strong></div></div><h3>Pourquoi cet événement s’est produit</h3><p>${esc(e.why)}</p><h3>Éléments disponibles</h3><ul class="evidence">${e.evidence.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>${e.resolution?`<h3>Preuve de traitement</h3><p>${esc(e.resolution)}</p>`:''}<div class="drawer-actionbar">${e.status!=='resolved'?gpBtn('gp-event-resolve','Documenter la résolution',e.id,'btn-primary'):gpBtn('gp-event-reopen','Rouvrir l’événement',e.id)}${e.decisionId?gpBtn('gov-decision-detail','Voir la décision',e.decisionId):''}${gpBtn('gov-policy-detail','Voir la règle',e.policyId,'btn-ghost')}</div>`});}

export function renderAdministration(s){const a=gp(s).admin,roles=a.roles.filter(r=>roleType==='all'||r.type===roleType);return `${gpHead('ADMINISTRATION','Un cadre explicite pour chaque rôle.','Le rôle fixe un plafond. Le mandat d’un agent peut toujours restreindre davantage ses permissions.',adminTab==='roles'&&!isSecurityView(s)?gpBtn('gp-create-role',`${icon('plus',16)} Créer un rôle`,'','btn-primary'):adminTab==='models'&&!isSecurityView(s)?gpBtn('gp-create-model',`${icon('plus',16)} Ajouter un modèle`,'','btn-primary'):'')}<div class="notice">${icon('lock',18)}<div><strong>${isSecurityView(s)?'Vue Sécurité · rôles en lecture seule.':'Administration de démonstration.'}</strong><p>Ces droits structurent l’espace local. Leur application côté serveur fait partie du raccordement aux moteurs.</p></div></div>${gpTabs([['roles','Rôles'],['people','Personnes et agents'],['models','Modèles'],['connectors',`Connecteurs (${a.connectorReviews.filter(c=>c.status==='pending').length})`]],adminTab,'gp-admin-tab')}${adminTab==='roles'?`${gpTabs([['all','Tous les rôles'],['human','Rôles humains'],['agent','Rôles agents']],roleType,'gp-role-type')}<div class="grid-3 gp-role-grid">${roles.map(r=>`<article class="card gp-role-card"><div class="row between">${badge(r.type==='agent'?'Agent':'Humain',r.type==='agent'?'purple':'neutral')}<span class="muted small">${({organization:'Organisation',group:'Fonction',team:'Équipe',own:'Individuel'})[r.scope]}</span></div><h2>${esc(r.name)}</h2><p>${esc(r.description)}</p><div class="row between"><span class="muted small">${Object.values(a.assignments).filter(x=>x===r.id).length} titulaire(s) · ${r.permissions.length} droits</span>${gpBtn('gp-role-detail','Voir',r.id,'btn-sm')}</div></article>`).join('')}</div>`:adminTab==='people'?`<div class="card table-wrap"><table class="data-table"><thead><tr><th>Membre</th><th>Équipe</th><th>Rôle</th><th>Périmètre</th><th></th></tr></thead><tbody>${s.agents.map(p=>{const r=a.roles.find(r=>r.id===a.assignments[p.id]);return `<tr><td><div class="person">${avatar(p)}<span>${esc(p.name)}</span></div></td><td>${esc(p.team)}</td><td>${esc(r?.name||'Non attribué')}</td><td>${({organization:'Organisation',group:'Fonction',team:'Équipe',own:'Individuel'})[r?.scope]||'—'}</td><td>${!isSecurityView(s)?gpBtn('gp-assign-role','Attribuer',p.id,'btn-sm btn-ghost'):badge('Lecture seule','neutral')}</td></tr>`;}).join('')}</tbody></table></div>`:adminTab==='models'?`<div class="grid-3">${a.models.map(m=>`<article class="card gp-model-card"><div class="row between"><span class="icon-box purple">${icon('bot',20)}</span>${badge(m.enabled?'Disponible':'Désactivé',m.enabled?'green':'neutral')}</div><h2>${esc(m.name)}</h2><p>${esc(m.purpose)}</p><div class="tag-list"><span class="tag">${esc(m.region)}</span><span class="tag">${esc(m.provider)}</span></div><div class="gp-model-budget"><small>Plafond mensuel</small><strong>${money(m.monthlyCap)}</strong></div>${!isSecurityView(s)?gpBtn('gp-edit-model','Configurer',m.id,'btn-sm'):''}</article>`).join('')}</div><p class="form-help">Catalogue de configuration local. Aucun appel de modèle n’est effectué dans cette démonstration.</p>`:renderConnectorReviews(s)}`;}
function roleDrawer(r,s,ctx){const holders=s.agents.filter(a=>gp(s).admin.assignments[a.id]===r.id);ctx.drawer({title:r.name,subtitle:`Rôle ${r.type==='agent'?'agent':'humain'} · périmètre ${r.scope}`,body:`<p>${esc(r.description)}</p>${permissionGroups.map(g=>`<h3>${g.title}</h3><div class="gp-permission-list">${g.items.map(([key,label])=>`<div class="row between"><span>${label}</span>${r.permissions.includes(key)?badge('Autorisé','green'):badge('Non accordé','neutral')}</div>`).join('')}</div>`).join('')}<div class="notice">Plafond d’engagement : ${money(r.moneyCap)}. Les règles de validation restent applicables.</div><h3>Titulaires</h3>${holders.map(a=>actorTile(a,s)).join('')||'<p class="muted small">Aucun titulaire pour le moment.</p>'}<div class="drawer-actionbar">${!isSecurityView(s)?gpBtn('gp-edit-role','Modifier les permissions',r.id,'btn-primary'):badge('Vue sécurité : lecture seule','neutral')}${!holders.length&&!isSecurityView(s)?gpBtn('gp-delete-role','Supprimer ce rôle',r.id,'btn-ghost'):''}</div>`});}
function roleForm(r,s,ctx){const initial=r||roleDefinition(gpId('role'),'','human','team',['data.read']);ctx.closeDrawer();ctx.modal({title:r?'Modifier les permissions':'Créer un rôle',subtitle:'Les permissions sont un plafond ; les mandats restent applicables.',body:`<div class="field"><label for="gp-role-name">Nom du rôle</label><input id="gp-role-name" name="name" value="${esc(initial.name)}" required maxlength="80"></div><div class="form-grid"><div class="field"><label for="gp-role-type">Type de titulaire</label><select id="gp-role-type" name="type">${gpOptions([['human','Personne'],['agent','Agent']],initial.type)}</select></div><div class="field"><label for="gp-role-scope">Périmètre maximum</label><select id="gp-role-scope" name="scope">${gpOptions([['own','Individuel'],['team','Équipe'],['group','Fonction'],['organization','Organisation']],initial.scope)}</select></div><div class="field"><label for="gp-role-cap">Plafond d’engagement (€)</label><input id="gp-role-cap" name="cap" type="number" min="0" max="100000000" value="${initial.moneyCap}" required></div></div>${permissionGroups.map(g=>`<fieldset class="gp-permission-fieldset"><legend>${g.title}</legend>${g.items.map(([key,label])=>`<label><input type="checkbox" name="permissions" value="${key}" ${initial.permissions.includes(key)?'checked':''}><span>${label}</span></label>`).join('')}</fieldset>`).join('')}`,onSubmit:fd=>{const type=String(fd.get('type')),name=String(fd.get('name')||'').trim(),current=ctx.getState();if(!name)return false;if(current.governancePlus.admin.roles.some(x=>x.id!==initial.id&&x.name.toLowerCase()===name.toLowerCase())){ctx.toast('Ce nom de rôle existe déjà.');return false;}const holders=current.agents.filter(x=>current.governancePlus.admin.assignments[x.id]===initial.id);if(holders.some(x=>x.type!==type)){ctx.toast('Le type doit rester compatible avec les titulaires actuels.');return false;}ctx.update(st=>{const roles=st.governancePlus.admin.roles,record={...initial,name,type,scope:String(fd.get('scope')),moneyCap:Number(fd.get('cap')),permissions:fd.getAll('permissions').map(String)};if(r)Object.assign(roles.find(x=>x.id===r.id),record);else roles.push(record);},r?'Permissions du rôle modifiées':'Rôle créé',name);ctx.toast('Le rôle est enregistré.');}});}
function modelForm(m,s,ctx){const initial=m||{id:gpId('model'),name:'',provider:'',region:'Europe',purpose:'',monthlyCap:500,enabled:false};ctx.modal({title:m?'Configurer le modèle':'Ajouter un modèle',subtitle:'Configuration du catalogue, sans clé API ni connexion réelle.',body:`<div class="field"><label for="gp-model-name">Nom</label><input id="gp-model-name" name="name" value="${esc(initial.name)}" required maxlength="80"></div><div class="form-grid"><div class="field"><label for="gp-model-provider">Fournisseur / passerelle</label><input id="gp-model-provider" name="provider" value="${esc(initial.provider)}" required maxlength="80"></div><div class="field"><label for="gp-model-region">Localisation</label><select id="gp-model-region" name="region">${gpOptions([['Europe','Europe'],['Sur site','Sur site'],['À définir','À définir']],initial.region)}</select></div><div class="field"><label for="gp-model-budget">Plafond mensuel (€)</label><input id="gp-model-budget" name="budget" value="${initial.monthlyCap}" type="number" min="0" max="1000000" required></div><div class="field"><label for="gp-model-enabled">Disponibilité</label><select id="gp-model-enabled" name="enabled">${gpOptions([['yes','Disponible'],['no','Désactivé']],initial.enabled?'yes':'no')}</select></div></div><div class="field"><label for="gp-model-purpose">Usage prévu</label><textarea id="gp-model-purpose" name="purpose" rows="2" required maxlength="500">${esc(initial.purpose)}</textarea></div>`,onSubmit:fd=>{const name=String(fd.get('name')||'').trim(),provider=String(fd.get('provider')||'').trim();if(!name||!provider){ctx.toast('Renseignez le nom et le fournisseur.');return false;}ctx.update(st=>{const record={...initial,name,provider,region:String(fd.get('region')),monthlyCap:Number(fd.get('budget')),enabled:fd.get('enabled')==='yes',purpose:String(fd.get('purpose')||'').trim()};if(m)Object.assign(st.governancePlus.admin.models.find(x=>x.id===m.id),record);else st.governancePlus.admin.models.push(record);},'Catalogue modèles modifié',name);ctx.toast('La configuration du modèle est enregistrée.');}});}

export function handleGovernancePlus(action,el,ctx){if(handleInsights(action,el,ctx))return true;if(!action.startsWith('gp-'))return false;const s=ctx.getState(),a=gp(s),id=el.dataset.id,value=el.dataset.value;
 if(action==='gp-workforce-mode'){workforceMode=value;ctx.render();}
 else if(action==='gp-workforce-type'){workforceType=value;ctx.render();}
 else if(action==='gp-workforce-clear'){workforceTeam='all';workforceManager='all';ctx.render();}
 else if(action==='gp-workforce-filters')ctx.modal({title:'Filtrer l’organisation',body:`<div class="field"><label for="gp-filter-team">Fonction</label><select id="gp-filter-team" name="team">${gpOptions([['all','Toutes les fonctions'],...[...new Set(s.agents.map(a=>a.team))].map(x=>[x,x])],workforceTeam)}</select></div><div class="field"><label for="gp-filter-manager">Sous la responsabilité de</label><select id="gp-filter-manager" name="manager">${gpOptions([['all','Toute l’organisation'],...s.agents.filter(a=>a.type==='human').map(a=>[a.id,a.name])],workforceManager)}</select></div>`,submitLabel:'Appliquer',onSubmit:fd=>{workforceTeam=String(fd.get('team'));workforceManager=String(fd.get('manager'));ctx.render();}});
 else if(action==='gp-person'){const p=s.agents.find(x=>x.id===id);if(p)personDrawer(p,s,ctx);}
 else if(action==='gp-create-person')personForm(null,s,ctx);
 else if(action==='gp-edit-person'){const p=s.agents.find(x=>x.id===id);if(p)personForm(p,s,ctx);}
 else if(action==='gp-security-tab'){securityTab=value;ctx.render();}
 else if(action==='gp-event-filter'){eventFilter=value;ctx.render();}
 else if(action==='gp-security-event'){const e=a.security.events.find(x=>x.id===id);if(e)eventDrawer(e,s,ctx);}
 else if(action==='gp-event-reopen'){ctx.update(st=>{const e=st.governancePlus.security.events.find(x=>x.id===id);e.status='open';},'Événement sécurité rouvert',id);ctx.closeDrawer();ctx.toast('L’événement est rouvert.');}
 else if(action==='gp-event-resolve'){const e=a.security.events.find(x=>x.id===id);if(!e)return true;ctx.closeDrawer();ctx.modal({title:'Documenter le traitement',subtitle:e.title,body:`<div class="field"><label for="gp-event-outcome">Situation après traitement</label><select id="gp-event-outcome" name="status"><option value="resolved">Résolu</option><option value="contained">Contenu, suivi nécessaire</option></select></div><div class="field"><label for="gp-event-evidence">Preuves et actions réalisées</label><textarea id="gp-event-evidence" name="evidence" rows="4" required minlength="10" maxlength="1600" placeholder="Décrivez la mesure prise et les éléments qui la confirment."></textarea></div>`,submitLabel:'Enregistrer le traitement',onSubmit:fd=>{const proof=String(fd.get('evidence')||'').trim();if(proof.length<10){ctx.toast('Précisez les preuves du traitement.');return false;}ctx.update(st=>{const x=st.governancePlus.security.events.find(x=>x.id===id);x.status=String(fd.get('status'));x.resolution=proof;x.resolvedAt=new Date().toISOString();},'Événement sécurité traité',`${e.title} · ${proof}`);ctx.toast('Le traitement est documenté.');}});}
 else if(action==='gp-access-review'||action==='gp-connector-review'){const connector=action==='gp-connector-review',r=connector?a.admin.connectorReviews.find(x=>x.id===id):a.security.accessReviews.find(x=>x.id===id);if(!r)return true;ctx.modal({title:connector?'Examiner le connecteur':'Recertifier l’accès',subtitle:connector?r.name:s.agents.find(x=>x.id===r.actorId)?.name,body:`<div class="notice"><p>${esc(r.evidence)}</p></div><div class="field"><label for="gp-review-choice">Décision</label><select id="gp-review-choice" name="decision"><option value="approved">${connector?'Autoriser le périmètre de démonstration':'Maintenir l’accès'}</option><option value="rejected">${connector?'Refuser':'Retirer l’accès'}</option></select></div><div class="field"><label for="gp-review-proof">Motif et preuves</label><textarea id="gp-review-proof" name="proof" rows="3" required maxlength="1000"></textarea></div>`,submitLabel:'Enregistrer la décision',onSubmit:fd=>{const proof=String(fd.get('proof')||'').trim();if(!proof){ctx.toast('Ajoutez le motif de votre décision.');return false;}ctx.update(st=>{const x=connector?st.governancePlus.admin.connectorReviews.find(x=>x.id===id):st.governancePlus.security.accessReviews.find(x=>x.id===id);x.status=String(fd.get('decision'));x.resolution=proof;x.reviewedAt=new Date().toISOString();if(!connector&&x.status==='rejected'){const roleId=st.governancePlus.admin.assignments[x.actorId];x.revokedPermission=x.permission;const actor=st.agents.find(a=>a.id===x.actorId);actor.deniedPermissions=[...new Set([...(actor.deniedPermissions||[]),x.permission])];}},connector?'Revue de connecteur enregistrée':'Revue d’accès enregistrée',proof);ctx.toast('La revue est enregistrée dans le journal.');}});}
 else if(action==='gp-admin-tab'){adminTab=value;ctx.render();}
 else if(action==='gp-role-type'){roleType=value;ctx.render();}
 else if(action==='gp-role-detail'){const r=a.admin.roles.find(x=>x.id===id);if(r)roleDrawer(r,s,ctx);}
 else if(['gp-create-role','gp-edit-role','gp-delete-role','gp-assign-role','gp-create-model','gp-edit-model'].includes(action)&&isSecurityView(s)){ctx.toast('Les rôles sont en lecture seule dans la vue Sécurité.');return true;}
 else if(action==='gp-create-role')roleForm(null,s,ctx);
 else if(action==='gp-edit-role'){const r=a.admin.roles.find(x=>x.id===id);if(r)roleForm(r,s,ctx);}
 else if(action==='gp-delete-role'){const r=a.admin.roles.find(x=>x.id===id);if(!r)return true;if(Object.values(a.admin.assignments).includes(id)){ctx.toast('Réaffectez les titulaires avant de supprimer ce rôle.');return true;}ctx.closeDrawer();ctx.modal({title:'Supprimer ce rôle',subtitle:r.name,body:'<p>Ce rôle n’a aucun titulaire. Sa définition sera retirée du catalogue local.</p>',submitLabel:'Supprimer',onSubmit:()=>{ctx.update(st=>{st.governancePlus.admin.roles=st.governancePlus.admin.roles.filter(x=>x.id!==id);},'Rôle supprimé',r.name);ctx.toast('Le rôle a été supprimé.');}});}
 else if(action==='gp-assign-role'){const p=s.agents.find(x=>x.id===id);if(!p)return true;ctx.modal({title:'Attribuer un rôle',subtitle:p.name,body:`<div class="field"><label for="gp-assigned-role">Rôle ${p.type==='agent'?'agent':'humain'}</label><select id="gp-assigned-role" name="roleId">${gpOptions(a.admin.roles.filter(r=>r.type===p.type).map(r=>[r.id,r.name]),a.admin.assignments[p.id])}</select></div><p class="form-help">Le rôle définit le plafond. Les politiques et les restrictions du mandat continuent de s’appliquer.</p>`,onSubmit:fd=>{const roleId=String(fd.get('roleId')),r=ctx.getState().governancePlus.admin.roles.find(x=>x.id===roleId);if(!r||r.type!==p.type){ctx.toast('Rôle incompatible avec ce membre.');return false;}ctx.update(st=>{st.governancePlus.admin.assignments[id]=roleId;},'Rôle attribué',`${p.name} · ${r.name}`);ctx.toast('Le rôle est attribué.');}});}
 else if(action==='gp-create-model')modelForm(null,s,ctx);
 else if(action==='gp-edit-model'){const m=a.admin.models.find(x=>x.id===id);if(m)modelForm(m,s,ctx);}
 else return false;return true;
}

let insightPhase = null;
let insightSpendGroup = 'team';
const insightPhaseTitles = ['Fondations','Premier déploiement','Expansion maîtrisée','Passage à l’échelle','Optimisation','Organisation durable'];
const iHead=(eyebrow,title,description,actions='')=>`<div class="page-head"><div><div class="eyebrow">${eyebrow}</div><h1 class="page-title">${title}</h1><p class="page-description">${description}</p></div><div class="head-actions">${actions}</div></div>`;
const iButton=(action,label,id='',cls='btn',symbol='')=>`<button class="${cls}" data-action="${action}" ${id?`data-id="${esc(id)}"`:''}>${symbol?icon(symbol,16):''}${label}</button>`;
const iNumber=(data,key,min=0,max=1e9)=>{const x=Number(data.get(key));return Number.isFinite(x)&&x>=min&&x<=max?x:null;};
const iId=prefix=>`${prefix}-${Date.now().toString(36)}-${Math.random().toString(36).slice(2,6)}`;
const iMetric=(label,value,foot,tone='')=>`<div class="stat-card ${tone}"><span class="stat-label">${label}</span><strong class="stat-value">${value}</strong><span class="stat-foot">${foot}</span></div>`;
const iGet=s=>s.governancePlus||createInsightsSeed(s);

export function createInsightsSeed(s) {
 const teams=[...new Set(s.agents.map(a=>a.team))], total=s.agents.filter(a=>a.type==='agent').reduce((n,a)=>n+Number(a.cost||0),0);
 const checks=[
  [['sponsor','Sponsor et responsables nommés',true,'Matthieu pilote le programme ; chaque équipe possède un responsable.'],['identities','Identités et droits documentés',true,'Registre initial et mandats accessibles dans le démonstrateur.'],['baseline','Mesures de référence établies',true,'Jeu de référence fictif documenté ; branchement des sources à réaliser.']],
  [['usecase','Premier processus mis en service',true,'Le rapprochement quotidien possède des étapes et un responsable.'],['review','Revue humaine opérationnelle',true,'Les demandes de décision relient dossier, preuves et responsable.'],['quality','Qualité vérifiée sur un échantillon',true,'Qualification illustrative sur les données du scénario.']],
  [['functions','Trois équipes couvertes au minimum',true,'Opérations, investissement, conformité et distribution sont représentés.'],['safe','Limites et escalades testées',true,'Blocage des agents suspendus, approbation humaine et journal local.'],['funding','Trois parcours de transition financés',false,'Le parcours d’accompagnement reste à financer.'],['evidence','Résultats vérifiés par les métiers',false,'Une revue métier du pilote doit encore être documentée.']],
  [['capacity','Capacité et continuité organisées',false,'Définir les suppléants, la relève et les règles de continuité.'],['integration','Connecteurs de production qualifiés',false,'Temporal et Mastra ne sont pas raccordés dans la démonstration.'],['adoption','Adoption mesurée dans toutes les équipes',false,'Confirmer les usages avec une collecte validée.']],
  [['unit','Coût par résultat accepté piloté',false,'Relier les coûts réels et les mesures d’acceptation.'],['improve','Améliorations testées avant publication',false,'Mettre en place un protocole de comparaison sur échantillon.'],['reviews','Revues de mandat régulières',false,'Documenter une cadence de revue et ses comptes rendus.']],
  [['governance','Gouvernance inscrite dans les opérations',false,'Délégations, qualité et capacité revues dans les comités métiers.'],['sharing','Partage de valeur suivi',false,'Suivre les financements retenus et leurs bénéficiaires.'],['renewal','Compétences entretenues dans la durée',false,'Réévaluer les qualifications à chaque évolution significative.']]
 ];
 return {transformation:{phase:2,phases:insightPhaseTitles.map((title,n)=>({id:n,title,description:['Établir le cadre et les responsabilités.','Prouver la valeur sur un périmètre limité.','Étendre les usages avec un contrôle explicite.','Organiser la continuité et l’adoption.','Améliorer les résultats et le coût de service.','Faire évoluer durablement les métiers et leurs moyens.'][n],checks:checks[n].map(([id,label,met,evidence])=>({id,label,met,evidence}))})),maturity:teams.map((team,n)=>({team,phase:n===2?1:2,evidence:n===2?'Revue de qualification encore en cours.':'Processus simulés actifs ; propriétaires identifiés.'})),tracks:[{id:'evolve',name:'Faire évoluer les compétences',funded:true,budget:24000,owner:'Matthieu Keip',evidence:'Formation à la supervision, aux preuves et aux mandats.'},{id:'redeploy',name:'Réaffecter vers des missions utiles',funded:true,budget:16000,owner:'Claire Martin',evidence:'Temps dégagé consacré aux exceptions et à la qualité des données.'},{id:'transition',name:'Accompagner les transitions',funded:false,budget:0,owner:'Matthieu Keip',evidence:'Cadre d’accompagnement à définir avec les responsables humains.'}],sharing:{percent:20,allocation:'Formation et amélioration des conditions de travail',notes:'Hypothèse de réinvestissement à valider. Aucun gain réel constaté dans cette démonstration.'}},spend:{allocations:teams.map((team,n)=>({id:`allocation-${n}`,team,budget:team==='Opérations'?3000:team==='Investissement'?2200:1400})),assumptions:{humanHourly:65,agentMinutesPerOutcome:8,baselineMinutes:25,acceptanceRate:92,forecastMultiplier:1.35},modelCosts:[{id:'model-standard',name:'Modèle généraliste',cost:Math.round(total*.56),requests:1420},{id:'model-reasoning',name:'Modèle de raisonnement',cost:Math.round(total*.29),requests:380},{id:'model-compact',name:'Modèle compact',cost:Math.round(total*.15),requests:2180}],period:'Novembre 2026'}};
}

export function renderTransformation(s) {
 const t=iGet(s).transformation, selected=t.phases.find(p=>p.id===(insightPhase??t.phase))||t.phases[t.phase], ready=t.phases[t.phase].checks.every(c=>c.met), funded=t.tracks.filter(x=>x.funded).length;
 return `${iHead('PROGRAMME DE TRANSFORMATION','Une organisation qui apprend à déléguer.','Avancez par étapes, avec des preuves, des responsabilités et des moyens pour les équipes.',iButton('gp-promote-phase','Passer à la phase suivante','','btn btn-primary','arrow'))}
 <div class="gp-transform-banner"><div><span class="eyebrow">PHASE ${t.phase} · PROGRAMME EN COURS</span><h2>${esc(t.phases[t.phase].title)}</h2><p>${esc(t.phases[t.phase].description)}</p></div>${badge(ready?'Prête pour revue':'Critères à compléter',ready?'green':'amber')}</div>
 <div class="gp-phase-grid">${t.phases.map(p=>`<button class="gp-phase ${p.id===selected.id?'selected':''} ${p.id<t.phase?'complete':''}" data-action="gp-select-phase" data-id="${p.id}" aria-pressed="${p.id===selected.id}"><span>${p.id<t.phase?icon('check',14):p.id}</span><strong>${esc(p.title)}</strong><small>${p.checks.filter(c=>c.met).length}/${p.checks.length} critères</small></button>`).join('')}</div>
 <div class="grid-2 gp-transform-columns"><section class="card gp-panel"><div class="card-head"><div><span class="eyebrow">PHASE ${selected.id}</span><h2 class="card-title">${esc(selected.title)} : critères de passage</h2></div>${badge(`${selected.checks.filter(c=>c.met).length}/${selected.checks.length}`,'purple')}</div><div class="gp-checks">${selected.checks.map(c=>`<div class="gp-check"><span class="gp-check-icon ${c.met?'met':''}">${icon(c.met?'check':'clock',16)}</span><div><strong>${esc(c.label)}</strong><p>${esc(c.evidence)}</p><span>${badge(c.met?'Documenté':'À compléter',c.met?'green':'amber')}</span></div><button class="btn btn-ghost btn-sm" data-action="gp-edit-check" data-id="${selected.id}" data-check="${esc(c.id)}" aria-label="Modifier le critère ${esc(c.label)}">${icon('edit',15)}</button></div>`).join('')}</div></section>
 <section class="card gp-panel"><div class="card-head"><div><span class="eyebrow">ÉQUIPES</span><h2 class="card-title">Maturité par fonction</h2></div></div><div class="gp-maturity">${t.maturity.map(m=>`<button class="gp-maturity-row" data-action="gp-edit-maturity" data-id="${esc(m.team)}"><div><strong>${esc(m.team)}</strong><span>Phase ${m.phase} · ${esc(insightPhaseTitles[m.phase])}</span></div><div class="gp-maturity-dots" aria-label="Phase ${m.phase}">${insightPhaseTitles.map((_,n)=>`<i class="${n<=m.phase?'on':''}"></i>`).join('')}</div>${icon('chevron',15)}</button>`).join('')}</div><div class="gp-panel-note">Le niveau d’une équipe se décide sur ses preuves. Il ne change pas automatiquement avec la phase du programme.</div></section></div>
 <section class="card gp-panel gp-transition-section"><div class="card-head"><div><span class="eyebrow">ACCOMPAGNEMENT HUMAIN</span><h2 class="card-title">Trois parcours, des moyens explicites</h2></div>${badge(`${funded}/3 financés`,funded===3?'green':'amber')}</div><div class="gp-track-grid">${t.tracks.map(track=>`<article class="gp-track"><div class="row between"><span class="icon-box purple">${icon(track.id==='evolve'?'bot':track.id==='redeploy'?'users':'shield',19)}</span>${badge(track.funded?'Financé':'À financer',track.funded?'green':'amber')}</div><h3>${esc(track.name)}</h3><p>${esc(track.evidence)}</p><div class="gp-track-budget">${money(track.budget)} <small>enveloppe illustrative</small></div><span class="small muted">${esc(track.owner)}</span>${iButton('gp-edit-track','Ajuster le parcours',track.id,'btn btn-ghost btn-sm','edit')}</article>`).join('')}</div></section>
 <section class="card gp-sharing"><span class="gp-sharing-number">${fmt(t.sharing.percent)}<small>%</small></span><div><span class="eyebrow">PARTAGE DE VALEUR ENVISAGÉ</span><h2 class="card-title">${esc(t.sharing.allocation)}</h2><p>${esc(t.sharing.notes)}</p></div>${iButton('gp-edit-sharing','Configurer','','btn','sliders')}</section>`;
}

export function insightSpendMetrics(s) {
 const sp=iGet(s).spend,a=sp.assumptions,agents=s.agents.filter(x=>x.type==='agent'),actual=agents.reduce((n,x)=>n+Number(x.cost||0),0),cases=s.processes.reduce((n,p)=>n+Number(p.cases||0),0),accepted=Math.round(cases*a.acceptanceRate/100),savedHours=accepted*Math.max(0,a.baselineMinutes-a.agentMinutesPerOutcome)/60,gross=savedHours*a.humanHourly;
 return {actual,cases,accepted,savedHours,gross,net:gross-actual,unit:accepted?actual/accepted:0,forecast:actual*a.forecastMultiplier,budget:Number(s.settings.budget)||0};
}
function insightSpendRows(s,group) {
 const sp=iGet(s).spend,total=insightSpendMetrics(s).actual,actors=s.agents.filter(a=>a.type==='agent');
 if(group==='worker')return actors.map(a=>({id:a.id,label:a.name,detail:`${a.team} · ${a.role}`,cost:Number(a.cost)||0,budget:0,count:Number(a.hours)||0,countLabel:'heures',action:'gp-spend-worker'}));
 if(group==='process') {
  const rows=s.processes.map(p=>({id:p.id,label:p.name,detail:p.team,cost:p.agentIds.reduce((n,aid)=>{const a=actors.find(x=>x.id===aid),uses=s.processes.filter(x=>x.agentIds.includes(aid)).length;return n+(Number(a?.cost)||0)/Math.max(1,uses);},0),budget:0,count:p.cases,countLabel:'dossiers',action:'gp-spend-process'}));
  const unassigned=actors.filter(a=>!s.processes.some(p=>p.agentIds.includes(a.id))).reduce((n,a)=>n+Number(a.cost||0),0);if(unassigned)rows.push({id:'none',label:'Sans processus affecté',detail:'Coûts non répartis',cost:unassigned,budget:0,count:0,countLabel:'dossiers'});return rows;
 }
 if(group==='model'){const sum=sp.modelCosts.reduce((n,m)=>n+Number(m.cost),0);return sp.modelCosts.map(m=>({id:m.id,label:m.name,detail:'Ventilation illustrative',cost:sum?total*m.cost/sum:0,budget:0,count:m.requests,countLabel:'appels',action:'gp-edit-model-cost'}));}
 return [...new Set([...actors.map(a=>a.team),...sp.allocations.map(x=>x.team)])].map(team=>({id:team,label:team,detail:`${actors.filter(a=>a.team===team).length} agents`,cost:actors.filter(a=>a.team===team).reduce((n,a)=>n+Number(a.cost||0),0),budget:sp.allocations.find(x=>x.team===team)?.budget||0,count:actors.filter(a=>a.team===team).reduce((n,a)=>n+Number(a.hours||0),0),countLabel:'heures',action:'gp-edit-team-budget'}));
}
export function renderSpend(s) {
 const sp=iGet(s).spend,m=insightSpendMetrics(s),rows=insightSpendRows(s,insightSpendGroup),max=Math.max(1,...rows.map(r=>Math.max(r.cost,r.budget))),forecastOver=m.forecast>m.budget,allocationTotal=sp.allocations.reduce((n,a)=>n+Number(a.budget||0),0);
 return `${iHead('COÛT ET VALEUR','Mesurer le coût du travail accepté.','Suivez les moyens engagés et rendez explicites les hypothèses de valeur.',iButton('gp-edit-spend-assumptions','Hypothèses de calcul','','btn','sliders'))}
 <div class="gp-spend-period"><span>${icon('clock',15)} ${esc(sp.period)}</span>${badge('Données de démonstration','purple')}<span class="muted">${m.cases} dossiers · ${fmt(sp.assumptions.acceptanceRate)} % d’acceptation supposée</span></div>
 <div class="stat-grid gp-spend-stats">${iMetric('Dépense agents',money(m.actual),'Cumul du scénario')}${iMetric('Projection mensuelle',money(m.forecast),`Hypothèse × ${fmt(sp.assumptions.forecastMultiplier)}`,forecastOver?'gp-warning':'')}${iMetric('Budget mensuel',money(m.budget),`${fmt(m.budget?m.actual/m.budget*100:0)} % consommé`)}${iMetric('Coût / résultat accepté',money(m.unit),`${m.accepted} résultats estimés`)}</div>
 <div class="card gp-budget-track"><div class="row between"><strong>Consommation de l’enveloppe</strong><span>${money(m.actual)} / ${money(m.budget)}</span></div>${progress(m.budget?m.actual/m.budget*100:0,forecastOver?'amber':'purple')}<p>${forecastOver?'La projection illustrative dépasse l’enveloppe.':'La projection illustrative reste dans l’enveloppe.'} La projection applique le facteur de charge défini dans vos hypothèses.</p></div>
 <section class="card gp-panel gp-spend-breakdown"><div class="card-head"><div><span class="eyebrow">RÉPARTITION</span><h2 class="card-title">Où vont les ressources ?</h2></div><div class="filter-bar">${[['team','Équipe'],['process','Processus'],['model','Modèle'],['worker','Agent']].map(([key,label])=>`<button class="filter-btn ${insightSpendGroup===key?'active':''}" data-action="gp-spend-group" data-id="${key}">${label}</button>`).join('')}</div></div><div class="gp-spend-bars">${rows.map(r=>`<div class="gp-spend-bar-row"><div class="gp-spend-bar-label"><strong>${esc(r.label)}</strong><span>${esc(r.detail)}</span></div><div class="gp-spend-bar-chart"><div class="gp-bar-budget" style="width:${Math.max(1,r.budget/max*100)}%"></div><div class="gp-bar-actual" style="width:${Math.max(1,r.cost/max*100)}%"></div></div><strong>${money(r.cost)}</strong>${r.action?iButton(r.action,icon(r.action.startsWith('gp-edit')?'edit':'arrow',14),r.id,'btn btn-ghost btn-sm'):'<span></span>'}</div>`).join('')}</div><div class="gp-chart-legend"><span><i></i> Dépense du scénario</span>${insightSpendGroup==='team'?'<span><i class="budget"></i> Budget d’équipe</span>':''}</div><div class="table-wrap"><table class="data-table"><thead><tr><th>${{team:'Équipe',process:'Processus',model:'Modèle',worker:'Agent'}[insightSpendGroup]}</th><th>Dépense</th><th>Part</th><th>Activité</th>${insightSpendGroup==='team'?'<th>Budget</th>':''}</tr></thead><tbody>${rows.map(r=>`<tr><td>${esc(r.label)}</td><td>${money(r.cost)}</td><td>${fmt(m.actual?r.cost/m.actual*100:0)} %</td><td>${fmt(r.count)} ${r.countLabel}</td>${insightSpendGroup==='team'?`<td>${money(r.budget)} ${r.cost>r.budget?badge('Dépassé','amber'):''}</td>`:''}</tr>`).join('')}</tbody></table></div><div class="gp-panel-note">${insightSpendGroup==='process'?'Ventilation au prorata des processus affectés à chaque agent. Ce calcul ne remplace pas une mesure par exécution.':insightSpendGroup==='model'?'Répartition hypothétique paramétrable. Aucun relevé de fournisseur ni facture réelle n’est connecté.':insightSpendGroup==='team'?`Enveloppes d’équipe : ${money(allocationTotal)}. Budget global : ${money(m.budget)}. ${allocationTotal!==m.budget?'Les enveloppes doivent être rapprochées du budget global.':''}`:'Les coûts sont issus des fiches agents du scénario.'}</div></section>
 <div class="grid-2 gp-value-grid"><section class="card gp-value-card"><span class="eyebrow">TEMPS POTENTIELLEMENT LIBÉRÉ</span><strong class="gp-value-number">${fmt(m.savedHours)} <small>h</small></strong><p>${m.accepted} résultats estimés × (${fmt(sp.assumptions.baselineMinutes)} − ${fmt(sp.assumptions.agentMinutesPerOutcome)}) minutes de travail humain.</p><div class="row between"><span>Valorisation hypothétique</span><strong>${money(m.gross)}</strong></div><div class="row between"><span>Après coût des agents</span><strong>${money(m.net)}</strong></div></section><section class="card gp-value-card"><span class="eyebrow">COMMENT LIRE CES CHIFFRES</span><h2 class="card-title">Une hypothèse de capacité, à vérifier.</h2><p>Le temps valorisé ne constitue pas une économie de trésorerie. Il suppose que le temps libéré est réellement réutilisable et que la qualité reste acceptable.</p><ul class="evidence"><li>Taux d’acceptation supposé : ${fmt(sp.assumptions.acceptanceRate)} %.</li><li>Coût horaire humain supposé : ${money(sp.assumptions.humanHourly)}.</li><li>La supervision résiduelle est incluse dans ${fmt(sp.assumptions.agentMinutesPerOutcome)} min par résultat.</li></ul>${iButton('gp-edit-spend-assumptions','Ajuster les hypothèses','','btn btn-ghost btn-sm','edit')}</section></div>`;
}

export function handleInsights(action,el,ctx) {
 const s=ctx.getState(), t=s.governancePlus?.transformation,sp=s.governancePlus?.spend;if(!t||!sp)return false;
 if(action==='gp-select-phase'){insightPhase=Number(el.dataset.id);ctx.render();return true;}
 if(action==='gp-edit-check'){
  const p=t.phases.find(x=>x.id===Number(el.dataset.id)),c=p?.checks.find(x=>x.id===el.dataset.check);if(!c)return true;
  ctx.modal({title:'Documenter un critère de passage',subtitle:c.label,body:`<div class="field"><label for="gp-check-status">Situation</label><select id="gp-check-status" name="met"><option value="false" ${!c.met?'selected':''}>À compléter</option><option value="true" ${c.met?'selected':''}>Documenté</option></select></div><div class="field"><label for="gp-check-evidence">Éléments de preuve</label><textarea id="gp-check-evidence" name="evidence" required rows="4" maxlength="1500">${esc(c.evidence)}</textarea></div>`,onSubmit:fd=>{const text=String(fd.get('evidence')||'').trim();if(!text){ctx.toast('Documentez les éléments de preuve.');return false;}ctx.update(st=>Object.assign(st.governancePlus.transformation.phases.find(x=>x.id===p.id).checks.find(x=>x.id===c.id),{met:fd.get('met')==='true',evidence:text}),'Critère de transformation actualisé',c.label);ctx.toast('Le critère et ses preuves sont enregistrés.');}});return true;
 }
 if(action==='gp-promote-phase'){
  if(t.phase>=5){ctx.toast('Le programme est déjà dans sa dernière phase.');return true;}
  if(!t.phases[t.phase].checks.every(c=>c.met)){ctx.toast('Documentez tous les critères de la phase actuelle avant de poursuivre.');return true;}
  ctx.modal({title:'Valider le passage de phase',subtitle:`${t.phases[t.phase].title} → ${t.phases[t.phase+1].title}`,submitLabel:'Valider le passage',body:`<p>Tous les critères de la phase ${t.phase} sont documentés. Enregistrez le motif de cette décision de gouvernance.</p><div class="field"><label for="gp-phase-note">Décision et conditions</label><textarea id="gp-phase-note" name="note" required rows="4" maxlength="1200"></textarea></div>`,onSubmit:fd=>{const note=String(fd.get('note')||'').trim();if(!note){ctx.toast('Documentez votre décision.');return false;}const current=ctx.getState().governancePlus.transformation;if(current.phase!==t.phase||!current.phases[current.phase].checks.every(c=>c.met)){ctx.toast('Les critères ont changé. Réexaminez la phase.');return false;}ctx.update(st=>{st.governancePlus.transformation.phase++;st.governancePlus.transformation.lastDecision=note;},'Phase de transformation validée',note);insightPhase=t.phase+1;ctx.toast('Le programme passe à la phase suivante.');}});return true;
 }
 if(action==='gp-edit-maturity'){
  const m=t.maturity.find(x=>x.team===el.dataset.id);if(!m)return true;
  ctx.modal({title:'Maturité de l’équipe',subtitle:m.team,body:`<div class="field"><label for="gp-maturity">Phase atteinte</label><select id="gp-maturity" name="phase">${insightPhaseTitles.map((title,n)=>`<option value="${n}" ${n===m.phase?'selected':''}>${n} — ${title}</option>`).join('')}</select></div><div class="field"><label for="gp-maturity-evidence">Éléments observés</label><textarea id="gp-maturity-evidence" name="evidence" required rows="4" maxlength="1200">${esc(m.evidence)}</textarea></div>`,onSubmit:fd=>{const text=String(fd.get('evidence')||'').trim();if(!text){ctx.toast('Décrivez les éléments observés.');return false;}ctx.update(st=>Object.assign(st.governancePlus.transformation.maturity.find(x=>x.team===m.team),{phase:Number(fd.get('phase')),evidence:text}),'Maturité d’équipe actualisée',m.team);ctx.toast('La maturité de l’équipe est mise à jour.');}});return true;
 }
 if(action==='gp-edit-track'){
  const track=t.tracks.find(x=>x.id===el.dataset.id);if(!track)return true;
  ctx.modal({title:'Financer un parcours humain',subtitle:track.name,body:`<div class="form-grid"><div class="field"><label for="gp-track-funded">Financement</label><select id="gp-track-funded" name="funded"><option value="true" ${track.funded?'selected':''}>Financé</option><option value="false" ${!track.funded?'selected':''}>À financer</option></select></div><div class="field"><label for="gp-track-budget">Enveloppe (€)</label><input id="gp-track-budget" name="budget" type="number" min="0" max="100000000" step="100" value="${track.budget}" required></div></div><div class="field"><label for="gp-track-owner">Responsable</label><input id="gp-track-owner" name="owner" value="${esc(track.owner)}" required maxlength="100"></div><div class="field"><label for="gp-track-description">Actions et justification</label><textarea id="gp-track-description" name="evidence" required rows="4" maxlength="1500">${esc(track.evidence)}</textarea></div>`,onSubmit:fd=>{const budget=iNumber(fd,'budget'),funded=fd.get('funded')==='true',owner=String(fd.get('owner')||'').trim(),text=String(fd.get('evidence')||'').trim();if(budget===null||!owner||!text||(funded&&budget===0)){ctx.toast('Un parcours financé nécessite une enveloppe positive, un responsable et une justification.');return false;}ctx.update(st=>{Object.assign(st.governancePlus.transformation.tracks.find(x=>x.id===track.id),{funded,budget,owner,evidence:text});const check=st.governancePlus.transformation.phases[2].checks.find(x=>x.id==='funding');check.met=st.governancePlus.transformation.tracks.every(x=>x.funded&&x.budget>0);check.evidence=check.met?'Les trois parcours disposent d’un financement documenté.':'Un ou plusieurs parcours restent à financer.';},'Parcours humain actualisé',track.name);ctx.toast('Les moyens du parcours sont enregistrés.');}});return true;
 }
 if(action==='gp-edit-sharing'){
  ctx.modal({title:'Réinvestissement de la valeur',subtitle:'Une règle de partage à documenter et faire suivre.',body:`<div class="field"><label for="gp-share-percent">Part envisagée (%)</label><input id="gp-share-percent" name="percent" type="number" min="0" max="100" step="1" value="${t.sharing.percent}" required></div><div class="field"><label for="gp-share-allocation">Affectation</label><input id="gp-share-allocation" name="allocation" value="${esc(t.sharing.allocation)}" required maxlength="180"></div><div class="field"><label for="gp-share-notes">Conditions et suivi</label><textarea id="gp-share-notes" name="notes" rows="4" required maxlength="1500">${esc(t.sharing.notes)}</textarea></div>`,onSubmit:fd=>{const percent=iNumber(fd,'percent',0,100),allocation=String(fd.get('allocation')||'').trim(),notes=String(fd.get('notes')||'').trim();if(percent===null||!allocation||!notes){ctx.toast('Vérifiez les conditions de réinvestissement.');return false;}ctx.update(st=>st.governancePlus.transformation.sharing={percent,allocation,notes},'Partage de valeur documenté',allocation);ctx.toast('La règle de réinvestissement est enregistrée.');}});return true;
 }
 if(action==='gp-spend-group'){insightSpendGroup=el.dataset.id;ctx.render();return true;}
 if(action==='gp-edit-spend-assumptions'){
  const a=sp.assumptions;
  ctx.modal({title:'Hypothèses de coût et de valeur',subtitle:'Ces paramètres alimentent une estimation, pas une économie constatée.',body:`<div class="form-grid">${[['humanHourly','Coût horaire humain (€)',a.humanHourly,0,10000],['baselineMinutes','Temps humain initial (min)',a.baselineMinutes,0,100000],['agentMinutesPerOutcome','Supervision résiduelle (min)',a.agentMinutesPerOutcome,0,100000],['acceptanceRate','Taux d’acceptation (%)',a.acceptanceRate,0,100],['forecastMultiplier','Facteur de projection mensuelle',a.forecastMultiplier,1,20],['budget','Budget mensuel (€)',s.settings.budget,0,100000000]].map(([key,label,value,min,max])=>`<div class="field"><label for="gp-assumption-${key}">${label}</label><input id="gp-assumption-${key}" name="${key}" type="number" min="${min}" max="${max}" step="any" value="${value}" required></div>`).join('')}</div><p class="form-help">Temps libéré = résultats acceptés estimés × (temps initial − supervision), avec un plancher à zéro. Projection = coût actuel × facteur.</p>`,onSubmit:fd=>{const humanHourly=iNumber(fd,'humanHourly',0,10000),baselineMinutes=iNumber(fd,'baselineMinutes',0,100000),agentMinutesPerOutcome=iNumber(fd,'agentMinutesPerOutcome',0,100000),acceptanceRate=iNumber(fd,'acceptanceRate',0,100),forecastMultiplier=iNumber(fd,'forecastMultiplier',1,20),budget=iNumber(fd,'budget',0,100000000);if([humanHourly,baselineMinutes,agentMinutesPerOutcome,acceptanceRate,forecastMultiplier,budget].includes(null)){ctx.toast('Vérifiez les valeurs et leurs limites.');return false;}ctx.update(st=>{st.governancePlus.spend.assumptions={humanHourly,baselineMinutes,agentMinutesPerOutcome,acceptanceRate,forecastMultiplier};st.settings.budget=budget;},'Hypothèses de valeur actualisées','Coût, supervision, acceptation et projection.');ctx.toast('Les indicateurs ont été recalculés.');}});return true;
 }
 if(action==='gp-edit-team-budget'){
  const team=el.dataset.id,allocation=sp.allocations.find(x=>x.team===team);
  ctx.modal({title:'Enveloppe de l’équipe',subtitle:team,body:`<div class="field"><label for="gp-team-budget">Budget mensuel (€)</label><input id="gp-team-budget" name="budget" type="number" min="0" max="100000000" step="1" value="${allocation?.budget||0}" required></div><p class="form-help">Budget global : ${money(s.settings.budget)}. Cette enveloppe sert au pilotage de l’équipe ; le budget global est géré dans les hypothèses.</p>`,onSubmit:fd=>{const budget=iNumber(fd,'budget',0,100000000);if(budget===null){ctx.toast('Indiquez une enveloppe valide.');return false;}ctx.update(st=>{const row=st.governancePlus.spend.allocations.find(x=>x.team===team);if(row)row.budget=budget;else st.governancePlus.spend.allocations.push({id:iId('allocation'),team,budget});},'Budget d’équipe actualisé',`${team} · ${money(budget)}`);ctx.toast('L’enveloppe est mise à jour.');}});return true;
 }
 if(action==='gp-edit-model-cost'){
  const model=sp.modelCosts.find(x=>x.id===el.dataset.id);if(!model)return true;
  ctx.modal({title:'Hypothèse de ventilation par modèle',subtitle:model.name,body:`<div class="notice">Répartition illustrative du coût total, proportionnelle aux poids saisis. Aucun fournisseur n’est connecté.</div><div class="form-grid"><div class="field"><label for="gp-model-weight">Poids de répartition</label><input id="gp-model-weight" name="weight" type="number" min="0" max="100000000" step="any" value="${model.cost}" required></div><div class="field"><label for="gp-model-requests">Appels du scénario</label><input id="gp-model-requests" name="requests" type="number" min="0" max="1000000000" step="1" value="${model.requests}" required></div></div>`,onSubmit:fd=>{const cost=iNumber(fd,'weight',0,100000000),requests=iNumber(fd,'requests',0,1e9);if(cost===null||requests===null||(!cost&&!sp.modelCosts.some(x=>x.id!==model.id&&x.cost>0))){ctx.toast('Conservez au moins un poids de répartition positif.');return false;}ctx.update(st=>Object.assign(st.governancePlus.spend.modelCosts.find(x=>x.id===model.id),{cost,requests}),'Ventilation modèle ajustée',model.name);ctx.toast('La ventilation illustrative est recalculée.');}});return true;
 }
 if(action==='gp-spend-worker'){
  const a=s.agents.find(x=>x.id===el.dataset.id);if(!a)return true;ctx.drawer({title:a.name,subtitle:`${a.role} · ${a.team}`,body:`<div class="detail-grid"><div class="detail-item"><span>Coût du scénario</span><strong>${money(a.cost)}</strong></div><div class="detail-item"><span>Activité</span><strong>${fmt(a.hours)} h</strong></div><div class="detail-item"><span>Coût par heure suivie</span><strong>${money(a.hours?a.cost/a.hours:0)}</strong></div><div class="detail-item"><span>Responsable</span><strong>${esc(a.manager)}</strong></div></div><h3 class="section-title">Processus affectés</h3>${s.processes.filter(p=>p.agentIds.includes(a.id)).map(p=>`<button class="linked-row" data-action="wf-open" data-id="${esc(p.id)}">${icon('workflow',17)}<span>${esc(p.name)}</span>${icon('arrow',15)}</button>`).join('')}<p class="form-help">Les coûts sont fictifs. Le suivi opérationnel devra provenir des exécutions et des coûts de modèles réellement mesurés.</p>`});return true;
 }
 if(action==='gp-spend-process'){
  const p=s.processes.find(x=>x.id===el.dataset.id);if(!p)return true;const row=insightSpendRows(s,'process').find(x=>x.id===p.id),accepted=Math.round(p.cases*sp.assumptions.acceptanceRate/100);ctx.drawer({title:p.name,subtitle:'Ventilation illustrative du coût',body:`<div class="detail-grid"><div class="detail-item"><span>Coût réparti</span><strong>${money(row.cost)}</strong></div><div class="detail-item"><span>Dossiers suivis</span><strong>${p.cases}</strong></div><div class="detail-item"><span>Résultats acceptés estimés</span><strong>${accepted}</strong></div><div class="detail-item"><span>Coût par résultat accepté</span><strong>${money(accepted?row.cost/accepted:0)}</strong></div></div><p class="muted">Le coût de chaque agent est réparti à parts égales entre ses processus. Le taux d’acceptation provient des hypothèses du scénario.</p><button class="btn btn-primary" data-action="wf-open" data-id="${esc(p.id)}">${icon('workflow',16)} Ouvrir le processus</button>`});return true;
 }
 return false;
}
